.animated {
  background: linear-gradient(90deg, #4e73df, #1cc88a);
  background-size: 200% 100%;
  animation: gradient 2s ease infinite;
}

@keyframes gradient {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

