}

.segmentLabel {
  display: flex;
  align-items: center;
  font-size: 0.875rem;
  color: #5a5c69;
}

.colorIndicator {
  display: inline-block;
  width: 0.75rem;
  height: 0.75rem;
  border-radius: 50%;
